import { createMcpHandler } from "agents/mcp";
import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { registerJinaTools } from "./tools/jina-tools.js";
import { stringify as yamlStringify } from "yaml";

// Build-time constants (can be replaced by build tools)
const SERVER_VERSION = "1.9.0";
const SERVER_NAME = "jina-mcp";

// Tool tags mapping for filtering
const TOOL_TAGS: Record<string, string[]> = {
	search: ["search_web", "search_arxiv", "search_ssrn", "search_images", "search_jina_blog"],
	read: ["read_url", "capture_screenshot_url"],
	utility: ["primer", "guess_datetime_url", "extract_pdf"],
	rerank: ["sort_by_relevance", "deduplicate_strings"],
};

// All available tools
const ALL_TOOLS = [
	"primer", "read_url", "capture_screenshot_url", "guess_datetime_url",
	"search_web", "search_arxiv", "search_ssrn", "search_images", "search_jina_blog",
	"sort_by_relevance", "deduplicate_strings", "extract_pdf"
];
// Parse tool filter from query parameters
function parseToolFilter(url: URL): Set<string> | null {
	const includeTools = url.searchParams.get("include_tools");
	const excludeTools = url.searchParams.get("exclude_tools");
	const includeTags = url.searchParams.get("include_tags");
	const excludeTags = url.searchParams.get("exclude_tags");

	// If no filters specified, return null (all tools enabled)
	if (!includeTools && !excludeTools && !includeTags && !excludeTags) {
		return null;
	}

	// Start with all tools, unless include_tags or include_tools is specified (then start empty)
	let enabledTools = (includeTags || includeTools)
		? new Set<string>()
		: new Set<string>(ALL_TOOLS);

	// Apply include_tags first (lowest priority) - add tagged tools
	if (includeTags) {
		const tags = includeTags.split(",").map(t => t.trim().toLowerCase());
		for (const tag of tags) {
			if (TOOL_TAGS[tag]) {
				for (const tool of TOOL_TAGS[tag]) {
					enabledTools.add(tool);
				}
			}
		}
	}

	// Apply include_tools - add specific tools
	if (includeTools) {
		const tools = includeTools.split(",").map(t => t.trim());
		for (const tool of tools) {
			if (ALL_TOOLS.includes(tool)) {
				enabledTools.add(tool);
			}
		}
	}

	// Apply exclude_tags - remove tagged tools
	if (excludeTags) {
		const tags = excludeTags.split(",").map(t => t.trim().toLowerCase());
		for (const tag of tags) {
			if (TOOL_TAGS[tag]) {
				for (const tool of TOOL_TAGS[tag]) {
					enabledTools.delete(tool);
				}
			}
		}
	}

	// Apply exclude_tools last (highest priority) - remove specific tools
	if (excludeTools) {
		const tools = excludeTools.split(",").map(t => t.trim());
		for (const tool of tools) {
			enabledTools.delete(tool);
		}
	}

	return enabledTools;
}


// Server instructions for MCP tool discovery (SEO for LLM tool search).
// Kept to what actually routes a request: which tool, and the distinctions
// between near-identical ones. The phrase lists this replaced restated the tool
// names in a dozen ways each and were paid for on every request.
const SERVER_INSTRUCTIONS = `Web access: search the live web, read URLs, search academic papers, and run Jina embedding/reranker utilities.

Use for anything online - current events, a URL the user pasted, a claim needing a source. Not for local files, code execution, or databases.

Picking a tool:
- search_web returns titles, URLs and engine snippets. For page-level passages, pass \`question\` to read_url on the results you chose. A snippet is not a source for exact values: verify version numbers, commands and error strings against the page.
- read_url fetches one page as markdown. Pass its \`question\` to get only the answering passages instead of the whole body; this is much cheaper than reading a full page into context.
- \`search_web\`, \`search_arxiv\`, \`search_ssrn\` and \`read_url\` accept an array on \`query\`/\`url\`; pass an array to run them concurrently instead of repeating single calls.
- search_arxiv for preprints, search_ssrn for social science and finance, search_jina_blog for Jina's own models and releases.
- primer supplies the current time and user location; call it before answering anything time- or location-dependent.`;

// Create the MCP server instance with request-scoped props
// Note: We create a fresh server per request to avoid race conditions with concurrent requests
// The props are captured in the closure at creation time, ensuring each request has its own context
function createServer(enabledTools: Set<string> | null, props: Record<string, unknown>) {
	const server = new McpServer(
		{
			name: "Jina AI Official MCP Server",
			version: SERVER_VERSION,
		},
		{
			instructions: SERVER_INSTRUCTIONS,
		}
	);

	// Register all Jina AI tools with props captured in closure (request-scoped)
	registerJinaTools(server, () => props, enabledTools);

	return server;
}

export default {
	async fetch(request: Request, env: Env, ctx: ExecutionContext) {
		const url = new URL(request.url);
		const cf = request.cf;

		// Parse tool filter from query parameters
		const enabledTools = parseToolFilter(url);

		// Build props for this request
		const props: Record<string, unknown> = { enabledTools };

		// Extract bearer token from Authorization header
		const authHeader = request.headers.get("Authorization");
		if (authHeader?.startsWith("Bearer ")) {
			props.bearerToken = authHeader.substring(7);
		}

		// No shared fallback key: a caller without a key gets the tools that work
		// anonymously (read_url via r.jina.ai) and a "set your API key" message
		// from the rest, rather than everyone spending one deployment key.

		// Add Ghost API key for Jina blog search
		props.ghostApiKey = env.VITE_GHOST_API_KEY;

		// API base URL for embedding/reranker endpoints (bypasses Cloudflare proxy issues)
		props.apiBaseUrl = env.API_BASE_URL || 'https://api.jina.ai';

		// Client identity for the response-size guardrail. This server is stateless -
		// createMcpHandler gets no `storage`, so WorkerTransport never replays the
		// `initialize` params into the per-request server and
		// server.getClientVersion() is undefined during `tools/call`. Pass the
		// transport User-Agent as a fallback hint, and let any client state its own
		// budget explicitly with ?max_tokens= (0 disables truncation).
		props.clientHint = request.headers.get("User-Agent") || undefined;

		const maxTokensParam = url.searchParams.get("max_tokens");
		if (maxTokensParam !== null) {
			const parsed = Number.parseInt(maxTokensParam, 10);
			if (Number.isFinite(parsed) && parsed >= 0) {
				props.maxResponseTokens = parsed;
			}
		}

		// Extract context information for the primer tool
		const context: any = {};

		// Add timestamp info
		context.timestamp = {
			utc: new Date().toISOString(),
		};
		if (cf?.timezone) {
			context.timestamp.userTimezone = cf.timezone;
			context.timestamp.userLocalTime = new Date().toLocaleString('en-US', { timeZone: cf.timezone as string });
		}

		// Add client info (only if values exist)
		const client: any = {};
		const clientIp = request.headers.get('CF-Connecting-IP');
		const userAgent = request.headers.get('User-Agent');
		const acceptLanguage = request.headers.get('Accept-Language');

		if (clientIp) client.ip = clientIp;

		// r.jina.ai rate-limits anonymous reads per X-Forwarded-For. Without it,
		// every keyless caller would share the Worker's egress IP and one budget.
		props.clientIp = clientIp || undefined;
		if (userAgent) client.userAgent = userAgent;
		if (acceptLanguage) client.acceptLanguage = acceptLanguage;
		if (Object.keys(client).length > 0) context.client = client;

		// Add location info (only if values exist)
		const location: any = {};
		if (cf?.country) location.country = cf.country;
		if (cf?.city) location.city = cf.city;
		if (cf?.region) location.region = cf.region;
		if (cf?.regionCode) location.regionCode = cf.regionCode;
		if (cf?.continent) location.continent = cf.continent;
		if (cf?.postalCode) location.postalCode = cf.postalCode;
		if (cf?.metroCode) location.metroCode = cf.metroCode;
		if (cf?.timezone) location.timezone = cf.timezone;
		if (cf?.latitude && cf?.longitude) {
			location.coordinates = {
				lat: cf.latitude,
				lon: cf.longitude
			};
		}
		if (cf?.isEUCountry === "1") location.isEU = true;
		if (Object.keys(location).length > 0) context.location = location;

		// Add network info (only if values exist)
		const network: any = {};
		if (cf?.asn) network.asn = cf.asn;
		if (cf?.asOrganization) network.organization = cf.asOrganization;
		if (cf?.colo) network.datacenter = cf.colo;
		if (cf?.httpProtocol) network.protocol = cf.httpProtocol;
		if (cf?.tlsVersion) network.tlsVersion = cf.tlsVersion;
		if (Object.keys(network).length > 0) context.network = network;

		// Add context to props
		props.context = context;

		// Handle MCP endpoints using createMcpHandler (stateless, no Durable Objects)
		// /v1 is the primary endpoint, /sse is kept for backward compatibility
		if (url.pathname === "/v1" || url.pathname === "/sse" || url.pathname === "/sse/message") {
			// Create server with request-scoped props (fresh per request to avoid race
			// conditions). Built here rather than for every path: `/` and unknown
			// paths used to register all tools only to discard them.
			const server = createServer(enabledTools, props);
			const route = url.pathname === "/v1" ? "/v1" : "/sse";
			const handler = createMcpHandler(server, {
				route,
				corsOptions: {
					origin: "*",
					methods: "GET, POST, DELETE, OPTIONS",
					headers: "Content-Type, Accept, Authorization, mcp-session-id, MCP-Protocol-Version",
					exposeHeaders: "mcp-session-id",
				}
			});

			return handler(request, env, ctx);
		}

		// Handle root path with helpful information
		if (url.pathname === "/") {
			const info = {
				name: "Jina AI Official MCP Server",
				source_code: "https://github.com/jina-ai/MCP",
				description: "Official Model Context Protocol server for Jina AI APIs",
				version: SERVER_VERSION,
				package_name: SERVER_NAME,
				usage: `
{
	"mcpServers": {
	"jina-mcp-server": {
		"url": "https://mcp.jina.ai/v1",
		"headers": {
		"Authorization": "Bearer \${JINA_API_KEY}" // optional
		}
	}
	}
}
`,
				get_api_key: "https://jina.ai/api-dashboard/",
				endpoints: {
					v1: "/v1 - Primary endpoint",
					sse: "/sse - Alias for /v1 (backward compatibility)"
				},
				tool_filtering: {
					description: "Reduce token usage by filtering tools via query parameters",
					parameters: {
						exclude_tools: "Comma-separated tool names to exclude (e.g., search_web,search_arxiv)",
						include_tools: "Comma-separated tool names to include",
						exclude_tags: "Comma-separated tags to exclude (e.g., search,read)",
						include_tags: "Comma-separated tags to include",
						max_tokens: "Cap the size of read_url responses in tokens (0 disables truncation)"
					},
					tags: TOOL_TAGS,
					examples: [
						"/v1?exclude_tags=search - Exclude all search tools",
						"/v1?include_tags=search,read - Only include search and read tools",
						"/v1?exclude_tools=search_ssrn,search_images - Exclude specific tools"
					],
					precedence: "exclude_tools > exclude_tags > include_tools > include_tags"
				},
				tools: [
					"primer - Current time, user timezone, location and client context",
					"read_url - Read a web page or PDF as markdown; pass question for passages instead of the full body",
					"capture_screenshot_url - Capture a screenshot of a web page",
					"guess_datetime_url - Guess a page publish or last-update datetime with a confidence score",
					"search_web - Search the web; returns titles, URLs and engine snippets; query accepts an array",
					"search_arxiv - Search arXiv preprints; query accepts an array",
					"search_ssrn - Search SSRN working papers; query accepts an array",
					"search_images - Search the web for images",
					"search_jina_blog - Search Jina AI news at jina.ai/news",
					"sort_by_relevance - Rerank documents by relevance to a query",
					"deduplicate_strings - Select top-k semantically distinct strings",
					"extract_pdf - Extract figures, tables and equations from a PDF"
				]
			};

			return new Response(yamlStringify(info), {
				headers: { "Content-Type": "text/yaml" },
				status: 200
			});
		}

		// Return helpful 404 for unknown paths
		return new Response(yamlStringify({
			error: "Endpoint not found",
			message: `Path '${url.pathname}' is not available`,
			available_endpoints: ["/", "/v1", "/sse"],
			suggestion: "Use /v1 for MCP client connections"
		}), {
			headers: { "Content-Type": "text/yaml" },
			status: 404
		});
	},
};

// ============================================================================
// TOKEN GUARDRAIL - Prevents MCP tool responses from exceeding client limits
// ============================================================================

const MAX_TOKENS = 25000;

// Clients known to have 25k token limit on MCP tool responses
const GUARDRAIL_CLIENTS = [
    'claude-code',
    'claude-ai',      // Claude Desktop
    'cursor-vscode',  // Cursor
];

type TextContentItem = { type: 'text'; text: string };
type ImageContentItem = { type: 'image'; data: string; mimeType: string };
type ContentItem = TextContentItem | ImageContentItem;

interface TokenCountResult {
    num_tokens: number;
    tokenizer: string;
}

// /v1/segment rejects content of 64k characters or more ("Content length must be
// greater than 0 and less than 64k"), which is *exactly* the size range the
// guardrail cares about: 25k tokens of English prose is ~100k characters. Every
// oversized document therefore used to 400 - after uploading the whole body -
// and silently fall back to a flat chars/4 guess. Count in chunks instead.
const SEGMENT_MAX_CHARS = 60000;
const SEGMENT_TIMEOUT_MS = 15000;

/** Rough local estimate, used only when the API is unavailable */
function estimateTokens(content: string): number {
    // ~4 chars/token holds for Latin script but overshoots badly for CJK, where a
    // character is closer to one token. Split the difference by script mix rather
    // than assuming English.
    const cjkCount = (content.match(/[\u3040-\u30ff\u3400-\u4dbf\u4e00-\u9fff\uf900-\ufaff]/g) || []).length;
    const rest = content.length - cjkCount;
    return Math.ceil(cjkCount + rest / 4);
}

async function countSegmentChunk(chunk: string, bearerToken: string, apiBaseUrl: string): Promise<number> {
    const response = await fetch(`${apiBaseUrl}/v1/segment`, {
        method: 'POST',
        signal: AbortSignal.timeout(SEGMENT_TIMEOUT_MS),
        headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${bearerToken}`,
        },
        body: JSON.stringify({ content: chunk }),
    });

    if (!response.ok) {
        throw new Error(`segment failed: ${response.status}`);
    }

    const data = await response.json() as TokenCountResult;
    return data.num_tokens;
}

/**
 * Count tokens using Jina Segment API
 */
async function countTokens(content: string, bearerToken: string, apiBaseUrl: string = 'https://api.jina.ai'): Promise<number> {
    // /v1/segment needs a key; a keyless read_url would only collect a 401.
    if (!bearerToken) return estimateTokens(content);

    const chunks: string[] = [];
    for (let i = 0; i < content.length; i += SEGMENT_MAX_CHARS) {
        chunks.push(content.slice(i, i + SEGMENT_MAX_CHARS));
    }

    try {
        const counts = await Promise.all(
            chunks.map((chunk) => countSegmentChunk(chunk, bearerToken, apiBaseUrl))
        );
        // Summing per-chunk counts can differ from a single-pass count by at most
        // one token per boundary, which is immaterial against a 25k budget.
        return counts.reduce((sum, n) => sum + n, 0);
    } catch {
        return estimateTokens(content);
    }
}

/** Reserve a little budget for the "content was truncated" notice */
const TRUNCATION_NOTICE_TOKENS = 64;

/**
 * Aim below the client's limit rather than exactly at it.
 *
 * Two independent sources of error make an exact target unsafe:
 *  - /v1/segment tokenizes with cl100k, but the client counts with its *own*
 *    tokenizer. The same text yields different totals, and only the client's
 *    number decides whether the response is rejected.
 *  - The cut itself is a proportional character ratio, which assumes uniform
 *    token density across the document. Prose, code blocks and tables differ.
 *  - The client measures the *serialized* payload, not the text: JSON escaping
 *    turned 84,743 characters of content into 89,917 characters on the wire.
 */
const GUARDRAIL_SAFETY_FACTOR = 0.9;

/**
 * Hard ceiling on emitted bytes, independent of any tokenizer.
 *
 * The token budget above relies on cl100k agreeing with the client's tokenizer,
 * which it does not. This bound does not: a 25,000-token limit becomes 75,000
 * bytes, which no realistic page content can tokenize to more than 25,000 tokens
 * of. It holds for both ends of the density range - ASCII prose runs ~3.6
 * bytes/token, and CJK is ~3 UTF-8 bytes per character at roughly one token per
 * character.
 *
 * Calibrated against a real rejection: Project Gutenberg plain text measured
 * 3.597 characters per client token, so a 25,000-token target that trusted
 * cl100k alone (89,917 chars) was still refused. 75,000 bytes of the same text
 * is ~20,850 client tokens.
 */
const MAX_BYTES_PER_TOKEN = 3;

/** Slack for the JSON envelope, field names and escape sequences */
const SERIALIZATION_OVERHEAD_BYTES = 2048;

/** Longest prefix of `text` that fits in `maxBytes` when UTF-8 encoded */
function sliceToByteBudget(text: string, approxChars: number, maxBytes: number): string {
    let candidate = text.slice(0, Math.max(0, approxChars));
    // The char estimate can overshoot on multi-byte content; shrink until it fits
    while (candidate.length > 0 && Buffer.byteLength(candidate, 'utf8') > maxBytes) {
        candidate = candidate.slice(0, Math.floor(candidate.length * 0.95));
    }
    return candidate;
}

/**
 * Truncate text content items so the response fits the client's budget.
 *
 * - Token counts for every item are resolved concurrently. They used to be
 *   awaited one at a time, so a 5-URL parallel_read_url paid five *sequential*
 *   /v1/segment round-trips after the reads had already finished.
 * - Original item order is preserved (images used to be hoisted ahead of text).
 * - At least one text item always survives: previously, if the very first item
 *   was on its own over budget the loop broke immediately and the caller got a
 *   response with no text content at all, silently.
 * - Dropped/truncated content is reported instead of vanishing, so the model
 *   knows it is looking at a partial document.
 */
async function truncateContentItems(
    contentItems: ContentItem[],
    bearerToken: string,
    maxTokens: number = MAX_TOKENS,
    apiBaseUrl: string = 'https://api.jina.ai'
): Promise<ContentItem[]> {
    const textItems = contentItems.filter((item): item is TextContentItem => item.type === 'text');
    if (textItems.length === 0) {
        return contentItems;
    }

    // A token never spans fewer than one UTF-8 byte, so a response whose total
    // byte length is already within budget cannot exceed it in tokens. Checking
    // that first skips the /v1/segment round-trips entirely for ordinary pages,
    // instead of uploading every document just to be told it fits.
    const totalBytes = textItems.reduce((sum, item) => sum + Buffer.byteLength(item.text, 'utf8'), 0);
    if (totalBytes <= maxTokens) {
        return contentItems;
    }

    const tokenCounts = new Map<TextContentItem, number>();
    await Promise.all(
        textItems.map(async (item) => {
            tokenCounts.set(item, await countTokens(item.text, bearerToken, apiBaseUrl));
        })
    );

    const totalTokens = [...tokenCounts.values()].reduce((sum, n) => sum + n, 0);
    if (totalTokens <= maxTokens) {
        return contentItems;
    }

    // Two independent budgets: tokens (accurate when cl100k agrees with the
    // client) and bytes (tokenizer-independent). An item must satisfy both.
    const tokenBudget = Math.floor(maxTokens * GUARDRAIL_SAFETY_FACTOR) - TRUNCATION_NOTICE_TOKENS;
    const byteBudget = maxTokens * MAX_BYTES_PER_TOKEN - SERIALIZATION_OVERHEAD_BYTES;

    const kept: ContentItem[] = [];
    let usedTokens = 0;
    let usedBytes = 0;
    let droppedItems = 0;
    let truncated = false;

    for (const item of contentItems) {
        if (item.type !== 'text') {
            kept.push(item);
            continue;
        }

        const itemTokens = tokenCounts.get(item) ?? 0;
        const itemBytes = Buffer.byteLength(item.text, 'utf8');

        if (usedTokens + itemTokens <= tokenBudget && usedBytes + itemBytes <= byteBudget) {
            kept.push(item);
            usedTokens += itemTokens;
            usedBytes += itemBytes;
            continue;
        }

        // First item that does not fit: spend whatever budget is left on a prefix
        // of it, then drop the rest. This is what guarantees the caller always
        // gets *some* content back, even when item one alone blows the budget.
        const remainingTokens = tokenBudget - usedTokens;
        const remainingBytes = byteBudget - usedBytes;

        if (!truncated && remainingTokens > 0 && remainingBytes > 0 && itemTokens > 0) {
            // Proportional character cut under whichever budget binds first -
            // approximate, but token density is roughly uniform within a document
            const charsByTokens = Math.floor(item.text.length * (remainingTokens / itemTokens));
            const charsByBytes = Math.floor(item.text.length * (remainingBytes / itemBytes));
            const text = sliceToByteBudget(item.text, Math.min(charsByTokens, charsByBytes), remainingBytes);

            if (text.length > 0) {
                kept.push({ type: 'text', text });
                usedTokens = tokenBudget;
                usedBytes = byteBudget;
                truncated = true;
                continue;
            }
        }

        droppedItems++;
    }

    const notes: string[] = [];
    if (truncated) notes.push('content was truncated to fit the client token limit');
    if (droppedItems > 0) notes.push(`${droppedItems} further result(s) omitted`);
    if (notes.length > 0) {
        kept.push({
            type: 'text',
            text: `[jina-mcp] Response exceeded the ${maxTokens}-token client limit: ${notes.join('; ')}. Re-run with fewer URLs, or read the omitted URLs individually, to see the rest.`,
        });
    }

    return kept;
}

/**
 * Check if client needs token guardrail
 *
 * `clientName` can no longer come only from server.getClientVersion(): the MCP
 * `initialize` request that carries clientInfo is handled in a *different* Worker
 * invocation than the `tools/call` that needs it, and this deployment is stateless
 * (createMcpHandler gets no `storage`, so WorkerTransport never replays
 * initializeParams). getClientVersion() is therefore undefined at tool-call time
 * and this predicate always returned false - the whole truncation path was dead.
 * index.ts now also passes the transport User-Agent as a fallback hint.
 */
export function shouldApplyGuardrail(clientName: string | undefined): boolean {
    if (!clientName) return false;
    return GUARDRAIL_CLIENTS.some(c => clientName.toLowerCase().includes(c.toLowerCase()));
}

/**
 * Apply token guardrail to MCP tool response
 *
 * Applies to known limited clients (Claude Code, Claude Desktop, Cursor), or to
 * any client that states its own budget with `?max_tokens=` on the endpoint URL.
 * `?max_tokens=0` opts out entirely.
 */
export async function applyTokenGuardrail(
    response: { content: ContentItem[]; isError?: boolean },
    bearerToken: string,
    clientName?: string,
    apiBaseUrl: string = 'https://api.jina.ai',
    explicitMaxTokens?: number
): Promise<{ content: ContentItem[]; isError?: boolean }> {
    const maxTokens = explicitMaxTokens ?? (shouldApplyGuardrail(clientName) ? MAX_TOKENS : undefined);

    // Not a known limited client and no declared budget
    if (maxTokens === undefined || maxTokens <= 0) {
        return response;
    }

    if (response.isError) {
        return response;
    }

    const truncatedContent = await truncateContentItems(
        response.content,
        bearerToken,
        maxTokens,
        apiBaseUrl
    );

    return {
        ...response,
        content: truncatedContent
    };
}

// Submodular optimization utilities for string deduplication

export function cosineSimilarity(a: number[], b: number[]): number {
    if (a.length !== b.length) return 0;

    let dotProduct = 0;
    let normA = 0;
    let normB = 0;

    for (let i = 0; i < a.length; i++) {
        dotProduct += a[i] * b[i];
        normA += a[i] * a[i];
        normB += b[i] * b[i];
    }

    if (normA === 0 || normB === 0) return 0;
    return dotProduct / (Math.sqrt(normA) * Math.sqrt(normB));
}

/**
 * Pairwise cosine similarity matrix, clamped to non-negative so the
 * facility-location objective stays monotone submodular.
 *
 * Building this used to call cosineSimilarity() for all n^2 ordered pairs, which
 * re-derived both vector norms on every call - 3 passes over d floats per pair,
 * and every pair computed twice. Here the norms are computed once (O(n*d)) and
 * only the upper triangle is evaluated, so the dominant term drops from
 * 3*n^2*d to n^2*d/2. Results are bit-identical to the previous implementation.
 *
 * Returned as a flat Float64Array (n*n) to avoid n separate JS arrays.
 */
function buildSimilarityMatrix(embeddings: ArrayLike<number>[]): Float64Array {
    const n = embeddings.length;

    // sumSquares[i] and norms[i] are derived once per vector instead of once per pair
    const sumSquares = new Float64Array(n);
    const norms = new Float64Array(n);
    for (let i = 0; i < n; i++) {
        const v = embeddings[i];
        let total = 0;
        for (let t = 0; t < v.length; t++) total += v[t] * v[t];
        sumSquares[i] = total;
        norms[i] = Math.sqrt(total);
    }

    const matrix = new Float64Array(n * n);
    for (let i = 0; i < n; i++) {
        const vi = embeddings[i];
        const normI = norms[i];

        // Same expression cosineSimilarity(v, v) evaluates to, kept verbatim rather
        // than shortcut to 1: sqrt(x)*sqrt(x) is not exactly x in IEEE-754, and the
        // selection order depends on those last bits when gains tie.
        const self = sumSquares[i] === 0 ? 0 : sumSquares[i] / (normI * normI);
        matrix[i * n + i] = self > 0 ? self : 0;

        for (let j = i + 1; j < n; j++) {
            const vj = embeddings[j];
            let sim = 0;
            // cosineSimilarity() returns 0 for mismatched lengths or a zero vector
            if (vi.length === vj.length && sumSquares[i] !== 0 && sumSquares[j] !== 0) {
                let dot = 0;
                for (let t = 0; t < vi.length; t++) dot += vi[t] * vj[t];
                sim = dot / (normI * norms[j]);
            }
            // Clamp to non-negative to ensure monotone submodularity of the
            // facility-location objective (NaN falls through to 0, as before)
            const clamped = sim > 0 ? sim : 0;
            matrix[i * n + j] = clamped;
            matrix[j * n + i] = clamped;
        }
    }

    return matrix;
}

export function computeMarginalGainDiversity(
    newIdx: number,
    currentCoverage: number[],
    similarityMatrix: number[][]
): number {
    const n = similarityMatrix.length;
    let marginalGain = 0;
    const row = similarityMatrix[newIdx];
    for (let i = 0; i < n; i++) {
        const newCoverage = row[i] > currentCoverage[i] ? row[i] : currentCoverage[i];
        marginalGain += newCoverage - currentCoverage[i];
    }
    return marginalGain;
}

/** Marginal gain of adding `idx` to the selected set, over the flat matrix */
function marginalGain(
    matrix: Float64Array,
    n: number,
    idx: number,
    coverage: Float64Array
): number {
    let gain = 0;
    const offset = idx * n;
    for (let i = 0; i < n; i++) {
        const sim = matrix[offset + i];
        if (sim > coverage[i]) gain += sim - coverage[i];
    }
    return gain;
}

/** [gain, lastUpdatedIteration, index, insertionSeq] */
type HeapEntry = [number, number, number, number];

/**
 * Max-heap over marginal gains for the lazy-greedy loop.
 *
 * The previous implementation used a plain array as the queue: `shift()` is O(n)
 * and it re-ran a full `sort()` after *every* stale-gain re-insertion, so each
 * re-evaluation cost O(n log n) on top of the O(n) gain computation.
 *
 * Ties are broken by ascending insertion sequence, which is exactly what the old
 * stable `sort()` did (re-inserted entries were appended, so they sorted after
 * equal-gain entries already in the queue). Selections are therefore unchanged.
 */
class GainHeap {
    private items: HeapEntry[] = [];
    private seq = 0;

    get size(): number {
        return this.items.length;
    }

    private static higher(a: HeapEntry, b: HeapEntry): boolean {
        return a[0] !== b[0] ? a[0] > b[0] : a[3] < b[3];
    }

    push(gain: number, lastUpdated: number, index: number): void {
        const items = this.items;
        items.push([gain, lastUpdated, index, this.seq++]);
        let i = items.length - 1;
        while (i > 0) {
            const parent = (i - 1) >> 1;
            if (!GainHeap.higher(items[i], items[parent])) break;
            [items[parent], items[i]] = [items[i], items[parent]];
            i = parent;
        }
    }

    pop(): HeapEntry | undefined {
        const items = this.items;
        if (items.length === 0) return undefined;
        const top = items[0];
        const last = items.pop() as HeapEntry;
        if (items.length > 0) {
            items[0] = last;
            let i = 0;
            for (;;) {
                const left = 2 * i + 1;
                const right = left + 1;
                let best = i;
                if (left < items.length && GainHeap.higher(items[left], items[best])) best = left;
                if (right < items.length && GainHeap.higher(items[right], items[best])) best = right;
                if (best === i) break;
                [items[best], items[i]] = [items[i], items[best]];
                i = best;
            }
        }
        return top;
    }
}

export function lazyGreedySelection(embeddings: ArrayLike<number>[], k: number): number[] {
    const n = embeddings.length;
    if (k >= n) return Array.from({ length: n }, (_, i) => i);

    const matrix = buildSimilarityMatrix(embeddings);

    // Maintain current coverage vector (max similarity to selected set for each element)
    const coverage = new Float64Array(n);
    const selected: number[] = [];
    const picked = new Uint8Array(n);

    const heap = new GainHeap();
    for (let i = 0; i < n; i++) {
        heap.push(marginalGain(matrix, n, i, coverage), 0, i);
    }

    for (let iteration = 0; iteration < k && heap.size > 0; iteration++) {
        for (;;) {
            const top = heap.pop();
            if (!top) break;
            const [, lastUpdated, bestIdx] = top;

            if (picked[bestIdx]) continue;

            if (lastUpdated === iteration) {
                picked[bestIdx] = 1;
                selected.push(bestIdx);
                // Update coverage in O(n)
                const offset = bestIdx * n;
                for (let i = 0; i < n; i++) {
                    if (matrix[offset + i] > coverage[i]) coverage[i] = matrix[offset + i];
                }
                break;
            }

            // Stale gain: re-evaluate and re-insert (the "lazy" part of lazy greedy)
            heap.push(marginalGain(matrix, n, bestIdx, coverage), iteration, bestIdx);
        }
    }

    return selected;
}

export function lazyGreedySelectionWithSaturation(
    embeddings: ArrayLike<number>[],
    threshold: number = 1e-2
): { selected: number[], optimalK: number, values: number[] } {
    const n = embeddings.length;

    const matrix = buildSimilarityMatrix(embeddings);

    const coverage = new Float64Array(n);
    const selected: number[] = [];
    const picked = new Uint8Array(n);
    const values: number[] = [];

    const heap = new GainHeap();
    for (let i = 0; i < n; i++) {
        heap.push(marginalGain(matrix, n, i, coverage), 0, i);
    }

    let earlyStopK: number | null = null;
    for (let iteration = 0; iteration < n && heap.size > 0; iteration++) {
        for (;;) {
            const top = heap.pop();
            if (!top) break;
            const [, lastUpdated, bestIdx] = top;

            if (picked[bestIdx]) continue;

            if (lastUpdated === iteration) {
                picked[bestIdx] = 1;
                selected.push(bestIdx);

                // Compute current function value (coverage)
                const offset = bestIdx * n;
                let total = 0;
                for (let i = 0; i < n; i++) {
                    if (matrix[offset + i] > coverage[i]) coverage[i] = matrix[offset + i];
                    total += coverage[i];
                }
                values.push(total / n);

                // Early stop once the marginal gain (delta of the normalized objective)
                // falls below the threshold. The element that produced that sub-threshold
                // delta is itself redundant, so k is the count *before* it was added.
                if (values.length >= 2) {
                    const delta = values[values.length - 1] - values[values.length - 2];
                    if (delta < threshold) {
                        earlyStopK = values.length - 1;
                    }
                }

                break;
            }

            heap.push(marginalGain(matrix, n, bestIdx, coverage), iteration, bestIdx);
        }
        if (earlyStopK !== null) break;
    }

    // Choose k: prefer early stop detection; otherwise, use all collected values
    const optimalK = earlyStopK ?? values.length;
    const finalSelected = selected.slice(0, optimalK);

    return { selected: finalSelected, optimalK, values };
}

/**
 * Run `task` with a deadline, resolving to `onTimeout()` instead of rejecting.
 *
 * The parallel tools used to race `Promise.all([...])` against a single rejecting
 * timeout promise. When that timeout won, the whole batch rejected and the tool's
 * catch block turned every already-completed search/read into one generic error
 * string - work that had finished successfully was thrown away.
 *
 * Giving each task its own deadline keeps the slow one isolated: it degrades to
 * an error entry while its siblings return their real results. The timer is
 * always cleared, so a fast batch leaves no pending timers behind.
 */
export async function withDeadline<T>(
    task: () => Promise<T>,
    timeoutMs: number,
    onTimeout: () => T
): Promise<T> {
    let timer: ReturnType<typeof setTimeout> | undefined;

    const deadline = new Promise<T>((resolve) => {
        timer = setTimeout(() => resolve(onTimeout()), timeoutMs);
    });

    try {
        return await Promise.race([task(), deadline]);
    } finally {
        if (timer !== undefined) clearTimeout(timer);
    }
}

/**
 * Image downloader utility with queue system for handling multiple concurrent downloads
 * Uses Cloudflare Workers' built-in image transformation capabilities
 */

interface ProcessedImageResult {
    url: string;
    success: boolean;
    data?: string; // base64 encoded JPEG image
    mimeType: string; // always "image/jpeg"
    error?: string;
}

/**
 * Download and process images using Cloudflare Workers image transformation
 * Automatically resizes to max 800px longest edge and converts to JPEG
 * Handles both single and batch downloads with timeout support
 */
export interface ImageTransformOptions {
    /** Max width in pixels (default 800) */
    width?: number;
    /**
     * Max height in pixels (default 800), or `null` to constrain width only.
     *
     * `null` is what tall full-page screenshots need: `fit: 'scale-down'`
     * preserves the aspect ratio, so an 800x800 box turns a 1280x20000 pageshot
     * into a ~51px-wide sliver in which no text is legible.
     */
    height?: number | null;
}

export async function downloadImages(
    urls: string | string[],
    concurrencyLimit: number = 3,
    timeoutMs: number = 15000,
    transform: ImageTransformOptions = {}
): Promise<ProcessedImageResult[]> {
    // Normalize input to always be an array
    const urlArray = Array.isArray(urls) ? urls : [urls];

    if (urlArray.length === 0) {
        return [];
    }

    const deadline = Date.now() + timeoutMs;
    const maxHeight = transform.height === undefined ? 800 : transform.height;

    // Results are written by index, so the array always lines up with the input
    // order and a partial run leaves no holes - callers index into it positionally.
    const results: ProcessedImageResult[] = urlArray.map((url) => ({
        url,
        success: false,
        mimeType: "image/jpeg",
        error: "Download timed out",
    }));

    const downloadOne = async (url: string, remainingMs: number): Promise<ProcessedImageResult> => {
        try {
            // Skip SVG images as they can't be processed by Cloudflare image transformation
            if (url.toLowerCase().endsWith('.svg') || url.toLowerCase().includes('.svg?')) {
                return {
                    url,
                    success: false,
                    mimeType: "image/jpeg",
                    error: "SVG images are not supported for transformation"
                };
            }

            // Use Cloudflare Workers image transformation
            // This automatically handles resizing and format conversion
            const response = await fetch(url, {
                // Bound each request individually so one stalled host cannot burn
                // the whole budget, and so the connection is actually released
                signal: AbortSignal.timeout(remainingMs),
                cf: {
                    image: {
                        fit: 'scale-down',              // Never enlarge, only shrink
                        width: transform.width ?? 800,  // Max width
                        ...(maxHeight === null ? {} : { height: maxHeight }),
                        format: 'jpeg',    // Convert to JPEG
                        quality: 85,       // Good quality with reasonable file size
                        compression: 'fast' // Faster processing
                    }
                }
            } as any);

            if (!response.ok) {
                return {
                    url,
                    success: false,
                    mimeType: "image/jpeg",
                    error: `HTTP ${response.status}: ${response.statusText}`
                };
            }

            const arrayBuffer = await response.arrayBuffer();
            const base64Image = Buffer.from(arrayBuffer).toString('base64');

            return {
                url,
                success: true,
                data: base64Image,
                mimeType: "image/jpeg"
            };
        } catch (error) {
            return {
                url,
                success: false,
                mimeType: "image/jpeg",
                error: error instanceof Error ? error.message : String(error)
            };
        }
    };

    // A rolling pool rather than fixed batches: `queue.splice(0, limit)` +
    // Promise.all meant every batch ran at the speed of its slowest image, and a
    // timeout mid-batch discarded that batch's completed downloads entirely.
    // Here each worker takes the next index as soon as it frees up, and every
    // finished download is committed immediately.
    let next = 0;
    const worker = async () => {
        for (;;) {
            const index = next++;
            if (index >= urlArray.length) return;

            const remainingMs = deadline - Date.now();
            if (remainingMs <= 0) return; // leave the pre-filled timeout entry in place

            results[index] = await downloadOne(urlArray[index], remainingMs);
        }
    };

    const poolSize = Math.max(1, Math.min(concurrencyLimit, urlArray.length));
    await Promise.all(Array.from({ length: poolSize }, worker));

    return results;
}

import { z } from "zod";
import { stringify as yamlStringify } from "yaml";

import { handleApiError, checkBearerToken } from "../utils/api-error-handler.js";
import { downloadImages } from "../utils/image-downloader.js";
import { lazyGreedySelection, lazyGreedySelectionWithSaturation } from "../utils/submodular-optimization.js";
import { applyTokenGuardrail } from "../utils/token-guardrail.js";
import {
	executeParallelSearches,
	executeWebSearch,
	executeArxivSearch,
	executeSsrnSearch,
	executeImageSearch,
	executeJinaBlogSearch,
	type SearchWebArgs,
	type SearchArxivArgs,
	type SearchSsrnArgs,
	type SearchImageArgs,
	type SearchJinaBlogArgs,
